/* From Uiverse.io by abdinejad  - Tags: minimalist, card, box, hover effect, css */
.__UIV_SCOPE__ .card-container,
.__UIV_SCOPE__ .card-box,
.__UIV_SCOPE__ .card-head,
.__UIV_SCOPE__ .card-number-row,
.__UIV_SCOPE__ .card-details,
.__UIV_SCOPE__ .card-holder-col,
.__UIV_SCOPE__ .card-date-col {
  display: flex;
}
.__UIV_SCOPE__ .card-container {
  align-items: center;
  justify-content: center;
}
.__UIV_SCOPE__ .card-box {
  width: 340px;
  min-height: 160px;
  background: #fff;
  box-shadow: 0px 0px 15px -2px rgba(0, 0, 0, 0.1);
  border-radius: 18px;
  margin: 16px;
  padding: 1.5em;
  flex-direction: column;
  justify-content: space-around;
  gap: 1.2em;
}
.__UIV_SCOPE__ .card-head {
  justify-content: space-between;
  align-items: center;
}
.__UIV_SCOPE__ .card-chip svg {
  width: 32px;
  height: 32px;
}
.__UIV_SCOPE__ .card-chip svg path {
  fill: #636363;
}
.__UIV_SCOPE__ .card-logo svg {
  width: 48px;
  height: 48px;
}
.__UIV_SCOPE__ .card-number-row {
  justify-content: center;
  word-spacing: 1em;
  font-size: 1.3em;
  font-weight: 600;
}
.__UIV_SCOPE__ .card-box:hover .card-number-row {
  font-size: 1.32em;
}
.__UIV_SCOPE__ .card-details {
  justify-content: space-between;
  text-transform: uppercase;
}
.__UIV_SCOPE__ .card-holder-col {
  flex-direction: column;
  gap: 2px;
}
.__UIV_SCOPE__ .card-holder-title,
.__UIV_SCOPE__ .card-date-title {
  color: #bdbdbd;
  font-size: 0.7em;
}
.__UIV_SCOPE__ .card-holder-name {
  font-size: 1.1em;
  font-weight: 600;
}
.__UIV_SCOPE__ .card-date-col {
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}
